actions.script:
import mchile.test.DteCertificateGenerator

try {
    // Generate certificate with RUT extension using BouncyCastle
    Map certParams = [
        subjectDN: "CN=${organizationName},O=${organizationName},C=CL",
        personRut: rut,
        issuerRut: "96790240-3",  // SII RUT for testing
        keySize: 2048,
        validityDays: validityDays
    ]

    Map certResult = DteCertificateGenerator.generateCertificateWithRUT(certParams)

    // Extract certificate data
    java.security.cert.X509Certificate cert = certResult.certificate
    java.security.PrivateKey privateKey = certResult.privateKey
    java.security.PublicKey publicKey = certResult.publicKey

    // Encode to base64/PEM format
    java.util.Base64.Encoder encoder = java.util.Base64.getEncoder()

    // Certificate in PEM format
    byte[] certBytes = cert.getEncoded()
    String certBase64Lines = encoder.encodeToString(certBytes).replaceAll("(.{64})", '$1\n')
    certificateBase64 = "-----BEGIN CERTIFICATE-----\n" + certBase64Lines + "\n-----END CERTIFICATE-----"

    // Private key in PEM format
    byte[] privKeyBytes = privateKey.getEncoded()
    String privKeyBase64Lines = encoder.encodeToString(privKeyBytes).replaceAll("(.{64})", '$1\n')
    privateKeyBase64 = "-----BEGIN PRIVATE KEY-----\n" + privKeyBase64Lines + "\n-----END PRIVATE KEY-----"

    // Public key in PEM format  
    byte[] pubKeyBytes = publicKey.getEncoded()
    String pubKeyBase64Lines = encoder.encodeToString(pubKeyBytes).replaceAll("(.{64})", '$1\n')
    publicKeyBase64 = "-----BEGIN PUBLIC KEY-----\n" + pubKeyBase64Lines + "\n-----END PUBLIC KEY-----"

    // Certificate string (raw base64)
    certificateString = encoder.encodeToString(certBytes)

    // Verify RUT extraction works
    try {
        String extractedRut = DteCertificateGenerator.extractRutFromCertificate(cert)
        rutExtensionFound = (extractedRut != null)
        ec.logger.info("Generated certificate with RUT extension for ${organizationName}, extracted RUT: ${extractedRut}")
    } catch (Exception e) {
        rutExtensionFound = false
        ec.logger.warn("Could not extract RUT from generated certificate: ${e.message}")
    }

} catch (Exception e) {
    ec.logger.error("Failed to generate test certificate with RUT extension: ${e.message}")

    // Fallback to basic certificate without RUT extension
    ec.logger.warn("Falling back to basic certificate generation without RUT extension")

    Map basicCertResult = DteCertificateGenerator.generateBasicCertificate([
        subjectDN: "CN=${organizationName},O=${organizationName},C=CL",
        keySize: 2048,
        validityDays: validityDays
    ])

    if (basicCertResult) {
        java.security.cert.X509Certificate cert = basicCertResult.certificate
        java.security.PrivateKey privateKey = basicCertResult.privateKey
        java.security.PublicKey publicKey = basicCertResult.publicKey

        java.util.Base64.Encoder encoder = java.util.Base64.getEncoder()

        byte[] certBytes = cert.getEncoded()
        String certBase64Lines = encoder.encodeToString(certBytes).replaceAll("(.{64})", '$1\n')
        certificateBase64 = "-----BEGIN CERTIFICATE-----\n" + certBase64Lines + "\n-----END CERTIFICATE-----"

        byte[] privKeyBytes = privateKey.getEncoded()
        String privKeyBase64Lines = encoder.encodeToString(privKeyBytes).replaceAll("(.{64})", '$1\n')
        privateKeyBase64 = "-----BEGIN PRIVATE KEY-----\n" + privKeyBase64Lines + "\n-----END PRIVATE KEY-----"

        byte[] pubKeyBytes = publicKey.getEncoded()
        String pubKeyBase64Lines = encoder.encodeToString(pubKeyBytes).replaceAll("(.{64})", '$1\n')
        publicKeyBase64 = "-----BEGIN PUBLIC KEY-----\n" + pubKeyBase64Lines + "\n-----END PUBLIC KEY-----"

        certificateString = encoder.encodeToString(certBytes)
        rutExtensionFound = false

        ec.logger.info("Generated basic certificate for ${organizationName} (no RUT extension)")
    } else {
        ec.message.addError("Failed to generate any certificate for testing")
    }
}

import mchile.test.DteCertificateGenerator
// Create PKCS12 certificate data for storage in PartyDteParams Map pkcs12Params = [ subjectDN: "CN=${organizationName},O=${organizationName},C=CL", personRut: rut, issuerRut: "96790240-3", password: "test123", alias: "dte-cert-${partyId}" ]
Map pkcs12Result = DteCertificateGenerator.generateTestCertificateData(pkcs12Params) certDataPkcs12 = pkcs12Result.certData passCertPkcs12 = pkcs12Result.passCert rutExtensionFound = certResult.rutExtensionFound

if (dteConfig.certificate) {
    // Try both extraction methods
    try {
        rutFound = MoquiDTEUtils.getRutFromCertificate(dteConfig.certificate)
    } catch (Exception e) {
        rutFound = DteCertificateGenerator.extractRutFromCertificate(dteConfig.certificate)
    }

    certificateValid = (dteConfig.certificate.notAfter.time > System.currentTimeMillis())
    expirationDate = new Timestamp(dteConfig.certificate.notAfter.time)

    ec.logger.info("Certificate verification for party ${partyId}:")
    ec.logger.info("  RUT found: ${rutFound}")
    ec.logger.info("  Valid: ${certificateValid}")
    ec.logger.info("  Expires: ${expirationDate}")
}
